import {moveFor} from './engine.mjs';
import {cat,star} from './art.js';
export function powerEffect(c,f,ground,time){const a=f.move;if(!a||!['special','super'].includes(a.type))return;const m=moveFor(f,a.type),superMove=a.type==='super',p=(a.t-m.startup)/m.active;if(p>1.8)return;const alpha=p<0?.5:Math.max(0,1-Math.max(0,p-1)/.8);c.save();c.globalAlpha=alpha;c.translate(f.x,ground-f.y);c.scale(f.face,1);const size=superMove?1.65:1,col=f.cat.accent;
 if(p<0){c.strokeStyle=col;c.lineWidth=superMove?7:4;c.beginPath();c.ellipse(10,-65,100*(1+p*.5),70,0,0,Math.PI*2);c.stroke();for(let i=0;i<8;i++)star(c,Math.cos(i*.8+time*8)*110,-70+Math.sin(i*.8+time*8)*90,superMove?12:6,'#fff8c8');}
 else if(f.cat.id==='aki'){for(let i=1;i<= (superMove?5:3);i++){c.save();c.globalAlpha=alpha*(.35-i*.045);cat(c,f.cat,-i*55,0,1.07,1,{...f,move:null},time);c.restore();}c.strokeStyle='#fff1a1';c.lineWidth=superMove?9:5;for(let i=0;i<5;i++){c.beginPath();c.moveTo(-170-i*30,-35-i*25);c.lineTo(15,-65-i*18);c.lineTo(-15,-90-i*18);c.lineTo(m.range,-115-i*18);c.stroke();}star(c,m.range*.75,-100,50*size,'#fff9d4',6);}
 else if(f.cat.id==='plumo'){for(let i=0;i<3;i++){c.strokeStyle=i%2?'#fff5c5':col;c.lineWidth=(superMove?17:10)-i*2;c.beginPath();c.ellipse(55,0,(90+i*30+Math.min(1,p)*80)*size,(18+i*7)*size,0,0,Math.PI*2);c.stroke();}for(let i=0;i<10;i++){const angle=i*.65;c.fillStyle=i%2?'#fff4be':col;c.save();c.translate(35+Math.cos(angle)*150*size,-Math.abs(Math.sin(angle))*100*size);c.rotate(angle);c.fillRect(-9,-9,18,18);c.restore();}if(superMove){c.font='900 64px Impact,sans-serif';c.fillStyle='#fff3b9';c.fillText('CHONK!',-120,-190);}}
 else if(f.cat.id==='amy'){for(let i=0;i<9;i++){const a=i*.7+time*4;star(c,85+Math.cos(a)*70*size,-80+Math.sin(a)*70*size,(i%2?9:16)*size,i%2?'#fff8d0':col,5);}c.strokeStyle='#fff2b2';c.lineWidth=8;c.beginPath();c.arc(85,-80,65*size,0,Math.PI*2);c.stroke();}
 else{const reach=superMove?390:220;for(let i=0;i<3;i++){c.strokeStyle=i%2?'#fff4d6':col;c.lineWidth=i===0?11:4;c.beginPath();c.ellipse(reach*.5,-105,(105+i*18)*size,(105+i*18)*size,0,0,Math.PI*2);c.stroke();}for(let i=0;i<12;i++){let a=i*Math.PI/6+time*.9;star(c,reach*.5+Math.cos(a)*135*size,-105+Math.sin(a)*135*size,9+(i%3)*4,'#fff4d5');}if(superMove){c.fillStyle='#fff3d3';c.beginPath();c.arc(reach*.5,-110,80,0,Math.PI*2);c.fill();c.fillStyle='#8a73b8';c.beginPath();c.arc(reach*.5+29,-132,70,0,Math.PI*2);c.fill();}}
 c.restore();}
export function projectileEffect(c,q,time){c.save();c.translate(q.x,657-q.y);c.scale(q.dir,1);const big=q.type==='super',r=q.radius;c.globalAlpha=.35;c.fillStyle='#ffd69a';c.beginPath();c.ellipse(-r*2,0,r*3,r*.7,0,0,Math.PI*2);c.fill();c.globalAlpha=1;for(let i=0;i<(big?8:4);i++)star(c,-r-i*19,Math.sin(time*12+i)*r*.7,(big?13:7)*(1-i/10),i%2?'#ffad8a':'#fff2bc',5);c.rotate(time*5);star(c,0,0,r*1.5,'#fff8ce',6);star(c,0,0,r,'#ee9c85',5);star(c,0,0,r*.45,'#fffbe7',5);c.restore();}
export function superBackdrop(c,match,time){const f=[match.p,match.cpu].find(f=>f.move?.type==='super'&&f.move.t<.9);if(!f)return;const t=f.move.t,opacity=Math.min(1,t/.08)*Math.min(1,(.9-t)/.2);c.save();c.globalAlpha=opacity*.62;c.fillStyle='#201834';c.fillRect(0,153,1440,657);c.strokeStyle=f.cat.accent;c.lineWidth=4;for(let i=0;i<22;i++){const a=i*Math.PI/11+time*.04;c.beginPath();c.moveTo(f.x+Math.cos(a)*170,500-f.y+Math.sin(a)*170);c.lineTo(f.x+Math.cos(a)*1700,500-f.y+Math.sin(a)*1700);c.stroke();}c.globalAlpha=opacity;c.translate(720,210);c.rotate(-.025);c.fillStyle='#201834';c.fillRect(-500,-40,1000,77);c.textAlign='center';c.font='800 42px "Barlow Condensed",Impact,sans-serif';c.fillStyle='#fff4ca';c.fillText(f.cat.super.toUpperCase(),0,13);c.restore();}
